using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResource
{
    private static readonly Dictionary<string, object> _config = new()
    {
        ["appName"] = "McpHttpServer",
        ["version"] = "1.0.0",
        ["maxConnections"] = 100,
        ["features"] = new Dictionary<string, bool>
        {
            ["logging"] = true,
            ["metrics"] = true,
            ["tracing"] = false
        }
    };

    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "app-settings",
        Description = "Returns the application configuration data")]
    public static string GetAppSettings()
    {
        return JsonSerializer.Serialize(_config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features",
        Name = "app-features",
        Description = "Returns the enabled feature flags")]
    public static string GetFeatureFlags()
    {
        var features = (Dictionary<string, bool>)_config["features"];
        return JsonSerializer.Serialize(features, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Gets the current server status and uptime")]
    public static string GetStatus()
    {
        return $"Server is running. Uptime: {Environment.TickCount64 / 1000}s";
    }

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

